"use strict";
exports.main = (context = {}) => {
    const parameters = context.parameters || {};
    const delayMs = parameters.delayMs || 60_000;
    const startedAt = Date.now();
    return new Promise((resolve, __reject) => {
        setTimeout(() => resolve({
            status: 'success',
            elapsedMs: Date.now() - startedAt,
        }), delayMs);
    });
};
